def unique_paths_with_obstacles(grid):
    def f(r, c):               # obstacle-free paths from (0, 0) to (r, c)
        if r < 0 or c < 0 or grid[r][c] == 1:
            return 0
        if r == 0 and c == 0:
            return 1
        return f(r - 1, c) + f(r, c - 1)
    return f(len(grid) - 1, len(grid[0]) - 1)

