def unique_paths_with_obstacles(grid):
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]
    for r in range(m):
        for c in range(n):
            if grid[r][c] == 1:
                dp[r][c] = 0
            elif r == 0 and c == 0:
                dp[r][c] = 1
            else:
                up = dp[r - 1][c] if r else 0
                left = dp[r][c - 1] if c else 0
                dp[r][c] = up + left
    return dp[m - 1][n - 1]

def unique_paths_with_obstacles(grid):
    n = len(grid[0])
    prev = [0] * n
    prev[0] = 1                # phantom row: one way to enter the start
    for cells in grid:
        cur = [0] * n
        for c in range(n):
            if cells[c] == 0:
                cur[c] = prev[c] + (cur[c - 1] if c else 0)
        prev = cur
    return prev[-1]

def unique_paths_with_obstacles(grid):
    n = len(grid[0])
    row = [0] * n
    row[0] = 1
    for cells in grid:
        for c in range(n):
            if cells[c] == 1:
                row[c] = 0
            elif c > 0:
                row[c] += row[c - 1]
    return row[-1]
